// frontend.md §5.3: generated files start with a `Generated by <tool>` header naming an existing tool and are
// marked `linguist-generated=true` in .gitattributes. Strict since step E1 (generated-markers-baseline.json deleted):
// every entry of GENERATED_SOURCES and GENERATED_OUTPUTS in scan.mjs must carry both markers.
import test from 'node:test';
import assert from 'node:assert/strict';
import { generatedGaps, generatedHeader, generatedSourceFiles, listSources, readSource } from './scan.mjs';

const { gaps, gitAvailable } = generatedGaps();
const pick = kinds => Object.entries(gaps).flatMap(([entry, list]) => list.filter(g => kinds.includes(g)).map(g => `${entry}: ${g}`));

test('every listed generated source exists exactly once under client/src', () => {
  const bad = generatedSourceFiles().filter(g => g.files.length !== 1).map(g => `${g.entry}: ${g.files.length} matches`);
  assert.deepEqual(bad, []);
});

test('generated sources start with a `Generated by <existing tool>` header', () => {
  assert.deepEqual(pick(['header', 'missing', 'ambiguous']), [], 'generated sources without a header naming an existing tool');
});

test('generated files are linguist-generated in .gitattributes', t => {
  if (!gitAvailable) { t.skip('git is not available to evaluate .gitattributes'); return; }
  assert.deepEqual(pick(['gitattributes', 'missing']), [], 'generated files without linguist-generated=true');
});

test('no unlisted client/src file carries a generated header', () => {
  const listed = new Set(generatedSourceFiles().flatMap(g => g.files));
  const unlisted = listSources(['.ts', '.css']).filter(f => !listed.has(f) && generatedHeader(readSource(f)).generated);
  assert.deepEqual(unlisted, [], 'add the file to GENERATED_SOURCES in tests/frontend/architecture/scan.mjs');
});
